    // call panel
    boxAt(g, 0.22, 0.4, 0.08, M.plasticDark, 1.62, 1.25, 0.2);
    boxAt(g, 0.1, 0.06, 0.03, M.emissiveRed, 1.62, 1.36, 0.25, 0, 0, 0, false);
