      arm.rotation.y = 0.6 * s;
      g.add(arm);
      const leg = mesh(new THREE.CapsuleGeometry(0.09, 0.65, 4, 8), M.fabricDark, -0.15, 0.12, s * 0.22, 0, 0.2 * s, 0);
      leg.rotation.z = Math.PI / 2;
      g.add(leg);
