  function glassWindow(w = 3, h = 1.4) {
    const g = new THREE.Group();
    boxAt(g, w + 0.2, 0.12, 0.16, M.steelDark, 0, h / 2, 0);
    boxAt(g, w + 0.2, 0.12, 0.16, M.steelDark, 0, -h / 2, 0);
    boxAt(g, 0.1, h + 0.2, 0.16, M.steelDark, -w / 2, 0, 0);
