  // back spikes
  for (let i = 0; i < 5; i++) {
    const sp = mesh(new THREE.ConeGeometry(0.06, 0.2, 5), bone);
    sp.position.set(0, 0.9 - i * 0.12, -0.34);
    sp.rotation.x = -0.6;
    pelvis.add(sp);
