  addCollider(cx, cz, w, d, opts = {}) {
    this.colliders.push({
      minX: cx - w / 2, maxX: cx + w / 2,
      minZ: cz - d / 2, maxZ: cz + d / 2,
      nav: opts.nav !== false,
